  'rm.try_intro': '将请求发送到真实端点:PUT、POST 或 DELETE 会更改数据。在{as}中选择账户时,会像“应用 › REST API”那样为其签发短期令牌;不选则可以看到无令牌调用方得到的结果。',
  'rm.intro': 'RESTful 服务模块:模块是应用程序的一个基本路径,其模板是带 `:parameters` 的 URI,每个模板按方法有处理程序及其源:集合查询、单行、SQL、PL/pgSQL 块或媒体资源。处理程序以应用程序的数据库角色运行,调用方为 `meta.app_user()`,因此其授权和行级安全性适用;参数是绑定的,绝不会粘贴进 SQL。每个模块都有 OpenAPI 文档。模块属于其应用程序:随应用程序导出一起迁移(也在“共享组件 › RESTful 服务”中)。',
  'rm.source_help': '绑定变量,大写:路径参数({params})、查询参数和 JSON 正文字段;`:BODY` 是整个正文;`:APP_USER` 是调用方。值是绑定的,绝不会粘贴进 SQL。PL/pgSQL:一个块(`declare … begin … end` 或语句),用 `perform meta.rest_reply(jsonb_build_object(…), 201)` 应答。媒体:返回 `content_type`、`content` 以及可选 `filename` 的查询。',
  'rm.params_help': '每行一个:`name query|body|header [{types}] [required] [description]`。它们会进入 OpenAPI 文档和“试一试”表单;缺少必需参数时返回 400。header 参数读取以其名称(_ 换成 -)命名的请求标头(`x_request_id` 读取 `X-Request-Id`)。',
  'rm.e.params_line': '参数,第 {n} 行:请写 "name query", "name body" 或 "name header",然后可选写类型({types})、"required" 和描述。',
